SELECT 'batch_021_558e2e31_wav_07' AS batch_id,(SELECT COUNT(*) FROM song_masters WHERE id IN ('sm-upload-1de39a7a-1f1','sm-upload-424bd1ff-5a3','sm-upload-4fd0058b-e08','sm-upload-740bc22a-fef','sm-upload-ac402330-2bd','sm-upload-b2ddad51-47e','sm-upload-d60777bc-dc0') AND album_id='al-07915266661ed52013a2a9b3558e2e31') AS candidate_masters_in_target,(SELECT COUNT(*) FROM song_masters WHERE id IN ('sm-upload-1de39a7a-1f1','sm-upload-424bd1ff-5a3','sm-upload-4fd0058b-e08','sm-upload-740bc22a-fef','sm-upload-ac402330-2bd','sm-upload-b2ddad51-47e','sm-upload-d60777bc-dc0') AND album_id='pending-uploads') AS candidate_masters_still_pending,(SELECT COUNT(*) FROM albums WHERE id='al-07915266661ed52013a2a9b3558e2e31' AND name='Stay') AS target_album_rows,(SELECT song_count FROM albums WHERE id='al-07915266661ed52013a2a9b3558e2e31') AS stored_song_count,(SELECT COALESCE(SUM(si.size),0) FROM song_instances si JOIN song_masters sm ON sm.id=si.master_id WHERE sm.album_id='al-07915266661ed52013a2a9b3558e2e31') AS calculated_size;
